59	    mainType?: 'radar'
60	
61	    startAngle?: number
62	
63	    shape?: 'polygon' | 'circle'
64	
65	    // TODO. axisType seems to have issue.
66	    // axisType?: 'value' | 'log'
67	
68	    axisLine?: AxisBaseOption['axisLine']
69	    axisTick?: AxisBaseOption['axisTick']
