101	
102	    coordinateSystem: Radar;
103	
104	    private _indicatorModels: AxisBaseModel<InnerIndicatorAxisOption>[];
105	
106	    optionUpdated() {
107	        const boundaryGap = this.get('boundaryGap');
108	        const splitNumber = this.get('splitNumber');
109	        const scale = this.get('scale');
110	        const axisLine = this.get('axisLine');
111	        const axisTick = this.get('axisTick');
112	        // let axisType = this.get('axisType');
113	        const axisLabel = this.get('axisLabel');
114	        const nameTextStyle = this.get('axisName');
115	        const showName = this.get(['axisName', 'show']);
116	        const nameFormatter = this.get(['axisName', 'formatter']);
117	        const nameGap = this.get('axisNameGap');
118	        const triggerEvent = this.get('triggerEvent');
119	
120	        const indicatorModels = zrUtil.map(this.get('indicator') || [], function (indicatorOpt) {
121	            // PENDING
122	            if (indicatorOpt.max != null && indicatorOpt.max > 0 && !indicatorOpt.min) {
