// Regression test for https://github.com/apache/echarts/pull/21081 and
// https://github.com/apache/echarts/pull/21124
// radar emphasis/blur itemStyle, lineStyle and areaStyle should be set as
// state styles on symbols/polyline/polygon and win over normal styling.

import { createChart, removeChart } from '../../test/ut/core/utHelper';
import { EChartsType } from '../../src/echarts.all';
import Group from 'zrender/src/graphic/Group';
import Path from 'zrender/src/graphic/Path';

function getRadarItemGroups(chart: EChartsType): Group[] {
    const radarView = (chart as any)._chartsViews.filter(
        (view: any) => view.type === 'radar'
    )[0];
    return (radarView.group.children() as Group[]).filter(
        child => child instanceof Group
    );
}

function getParts(itemGroup: Group) {
    const polyline = itemGroup.childAt(0) as Path;
    const polygon = itemGroup.childAt(1) as Path;
    const symbolGroup = itemGroup.childAt(2) as Group;
    const symbol = symbolGroup.childAt(0) as Path;
    return { polyline, polygon, symbolGroup, symbol };
}

describe('radar state style precedence', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart({ width: 500, height: 400 });
        chart.setOption({
            animation: false,
            radar: {
                indicator: [
                    { name: 'a', max: 10 },
                    { name: 'b', max: 10 },
                    { name: 'c', max: 10 }
                ]
            },
            series: [{
                type: 'radar',
                emphasis: {
                    focus: 'self',
                    lineStyle: {
                        width: 4
                    },
                    itemStyle: {
                        color: 'blue',
                        borderWidth: 2,
                        opacity: 0.4
                    },
                    areaStyle: {
                        opacity: 0.9
                    }
                },
                blur: {
                    lineStyle: {
                        opacity: 0.3
                    },
                    itemStyle: {
                        opacity: 0.8,
                        color: 'red'
                    },
                    areaStyle: {
                        opacity: 0.1
                    }
                },
                data: [
                    { value: [1, 2, 3], name: 'd1' },
                    { value: [4, 5, 6], name: 'd2' }
                ]
            }]
        });
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('should set emphasis/blur state styles on symbols, polyline and polygon', function () {
        const itemGroups = getRadarItemGroups(chart);
        expect(itemGroups.length).toEqual(2);

        itemGroups.forEach(function (itemGroup) {
            const { polyline, polygon, symbol } = getParts(itemGroup);

            // Symbols should carry emphasis and blur itemStyle state styles.
            expect(symbol.states.emphasis.style.fill).toEqual('blue');
            expect(symbol.states.emphasis.style.opacity).toEqual(0.4);
            expect(symbol.states.emphasis.style.lineWidth).toEqual(2);
            expect(symbol.states.blur.style.fill).toEqual('red');
            expect(symbol.states.blur.style.opacity).toEqual(0.8);

            // Polyline should carry emphasis and blur lineStyle state styles.
            expect(polyline.states.emphasis.style.lineWidth).toEqual(4);
            expect(polyline.states.blur.style.opacity).toEqual(0.3);

            // Polygon should carry emphasis and blur areaStyle state styles.
            expect(polygon.states.emphasis.style.opacity).toEqual(0.9);
            expect(polygon.states.blur.style.opacity).toEqual(0.1);
        });
    });

    it('emphasis/blur itemStyle should win over normal style on state change', function () {
        const itemGroups = getRadarItemGroups(chart);
        const emphasized = getParts(itemGroups[0]);
        const blurred = getParts(itemGroups[1]);

        chart.dispatchAction({
            type: 'highlight',
            seriesIndex: 0,
            dataIndex: 0
        });

        // Emphasis state wins over default symbol styling.
        expect(emphasized.symbol.style.fill).toEqual('blue');
        expect(emphasized.symbol.style.opacity).toEqual(0.4);
        expect(emphasized.polyline.style.lineWidth).toEqual(4);

        // Blur state (from focus: 'self') wins over default symbol styling.
        expect(blurred.symbol.style.fill).toEqual('red');
        expect(blurred.symbol.style.opacity).toEqual(0.8);
        expect(blurred.polyline.style.opacity).toEqual(0.3);

        chart.dispatchAction({
            type: 'downplay',
            seriesIndex: 0,
            dataIndex: 0
        });

        // Back to normal state.
        expect(emphasized.symbol.style.fill).not.toEqual('blue');
        expect(blurred.symbol.style.fill).not.toEqual('red');
    });

});

