// Temporary sanity check for radar clockwise option (not committed).
import { createChart, removeChart } from '../../test/ut/core/utHelper';
import Radar from '../../src/coord/radar/Radar';

function getAngles(clockwise: boolean) {
    const chart = createChart({ width: 500, height: 400 });
    chart.setOption({
        animation: false,
        radar: {
            clockwise: clockwise,
            startAngle: 90,
            indicator: [
                { name: 'a', max: 10 },
                { name: 'b', max: 10 },
                { name: 'c', max: 10 },
                { name: 'd', max: 10 }
            ]
        },
        series: [{ type: 'radar', data: [{ value: [1, 2, 3, 4] }] }]
    });
    const radar = (chart.getModel().getComponent('radar') as any).coordinateSystem as Radar;
    const angles = radar.getIndicatorAxes().map(axis => axis.angle);
    removeChart(chart);
    return angles;
}

describe('radar clockwise', function () {
    it('default keeps counter-clockwise layout', function () {
        const angles = getAngles(false);
        // 4 indicators, startAngle 90deg: PI/2, 0, -PI/2, -PI (normalized)
        expect(angles[0]).toBeCloseTo(Math.PI / 2);
        expect(angles[1]).toBeCloseTo(0);
        expect(angles[2]).toBeCloseTo(-Math.PI / 2);
        expect(angles[3]).toBeCloseTo(-Math.PI);
    });
    it('clockwise flips the layout direction', function () {
        const angles = getAngles(true);
        expect(angles[0]).toBeCloseTo(Math.PI / 2);
        expect(angles[1]).toBeCloseTo(Math.PI);
        expect(angles[2]).toBeCloseTo(-Math.PI / 2);
        expect(angles[3]).toBeCloseTo(0);
    });
});
